begin;
-- Separate legal source: a franchise mandate is never represented by a commercial contract ID.
-- No provider, issuer, level, policy or completed proof is seeded or publicly importable.
create table private.franchise_mandate_signature_policies_v1(
 id uuid primary key default extensions.gen_random_uuid(),environment text not null check(environment in('DEVELOPMENT','STAGING','PRODUCTION')),
 issuer_organization_id uuid not null references public.organizations(id),version integer not null check(version>0),provider_config_id uuid not null references public.signature_provider_configs(id),
 minimum_level text not null check(minimum_level in('SIMPLE','ADVANCED','QUALIFIED')),require_certificate boolean not null default true,require_trusted_timestamp boolean not null default true,
 legal_approval_reference text not null check(length(btrim(legal_approval_reference))between 8 and 500),adapter_registration_reference text not null check(length(btrim(adapter_registration_reference))between 8 and 500),
 approved_by uuid not null references auth.users(id),reviewed_by uuid not null references auth.users(id),approved_at timestamptz not null,valid_until timestamptz,
 check(approved_by<>reviewed_by),check(valid_until is null or valid_until>approved_at),check(minimum_level='SIMPLE'or(require_certificate and require_trusted_timestamp)),unique(environment,issuer_organization_id,version)
);
create table private.franchise_mandate_signature_proofs_v1(
 id uuid primary key default extensions.gen_random_uuid(),legal_document_version_id uuid not null unique,
 source_kind text not null default'FRANCHISE_MANDATE'check(source_kind='FRANCHISE_MANDATE'),franchise_id uuid not null references public.franchises(id),
 source_mandate_version_id uuid not null references public.franchise_mandate_versions(id),source_version integer not null check(source_version>0),source_hash text not null check(source_hash~'^[0-9a-f]{64}$'),
 issuer_organization_id uuid not null references public.organizations(id),operator_organization_id uuid not null references public.organizations(id),policy_version_id uuid not null references private.franchise_mandate_signature_policies_v1(id),
 pdf_sha256 text not null check(pdf_sha256~'^[0-9a-f]{64}$'),pdf_storage_object_id uuid not null references storage.objects(id),evidence_storage_object_id uuid not null references storage.objects(id),
 source_binding_hash text not null check(source_binding_hash~'^[0-9a-f]{64}$'),provider_code text not null,provider_envelope_id text not null check(length(provider_envelope_id)between 8 and 300),provider_package_id text not null check(length(provider_package_id)between 8 and 300),
 provider_package_sha256 text not null check(provider_package_sha256~'^[0-9a-f]{64}$'),achieved_level text not null check(achieved_level in('SIMPLE','ADVANCED','QUALIFIED')),
 event_chain_hash text not null check(event_chain_hash~'^[0-9a-f]{64}$'),verified_events jsonb not null check(jsonb_typeof(verified_events)='array'and jsonb_array_length(verified_events)>=3),
 final_hash text not null unique check(final_hash~'^[0-9a-f]{64}$'),completed_at timestamptz not null,verified_at timestamptz not null,verification_reference text not null check(length(btrim(verification_reference))between 8 and 500),
 unique(provider_code,provider_envelope_id),unique(provider_code,provider_package_id),check(issuer_organization_id<>operator_organization_id)
);
create table private.franchise_mandate_signature_parties_v1(
 proof_id uuid not null references private.franchise_mandate_signature_proofs_v1(id),party_role text not null check(party_role in('ISSUER','OPERATOR')),
 organization_id uuid not null references public.organizations(id),signer_user_id uuid not null references auth.users(id),verified_email_sha256 text not null check(verified_email_sha256~'^[0-9a-f]{64}$'),
 achieved_level text not null check(achieved_level in('SIMPLE','ADVANCED','QUALIFIED')),provider_signer_reference text not null,provider_event_id text not null,
 authority_evidence_sha256 text not null check(authority_evidence_sha256~'^[0-9a-f]{64}$'),authority_source_hash text not null check(authority_source_hash~'^[0-9a-f]{64}$'),
 authority_valid_from timestamptz not null,authority_valid_until timestamptz,authority_verified_by uuid not null references auth.users(id),authority_reviewed_by uuid not null references auth.users(id),
 certificate_fingerprint text check(certificate_fingerprint~'^[0-9a-f]{64}$'),certificate_status text check(certificate_status in('VERIFIED','REVOKED','UNAVAILABLE')),
 certificate_qualification text check(certificate_qualification in('QUALIFIED','NOT_QUALIFIED','UNKNOWN')),certificate_valid_from timestamptz,certificate_valid_until timestamptz,
 timestamp_token_hash text check(timestamp_token_hash~'^[0-9a-f]{64}$'),timestamp_status text check(timestamp_status in('VERIFIED','REJECTED','UNAVAILABLE')),timestamped_at timestamptz,
 signed_at timestamptz not null,primary key(proof_id,party_role),unique(proof_id,organization_id),unique(proof_id,signer_user_id),unique(proof_id,provider_signer_reference),unique(proof_id,provider_event_id),
 check(authority_verified_by<>authority_reviewed_by and signer_user_id not in(authority_verified_by,authority_reviewed_by)),check(authority_valid_until is null or authority_valid_until>authority_valid_from)
);
revoke all on private.franchise_mandate_signature_policies_v1,private.franchise_mandate_signature_proofs_v1,private.franchise_mandate_signature_parties_v1 from public,anon,authenticated,service_role;
create trigger franchise_mandate_signature_policies_immutable before update or delete on private.franchise_mandate_signature_policies_v1 for each row execute function private.prevent_contract_immutable_change();
create trigger franchise_mandate_signature_proofs_immutable before update or delete on private.franchise_mandate_signature_proofs_v1 for each row execute function private.prevent_contract_immutable_change();
create trigger franchise_mandate_signature_parties_immutable before update or delete on private.franchise_mandate_signature_parties_v1 for each row execute function private.prevent_contract_immutable_change();
create function private.franchise_mandate_source_binding_hash_v1(p_proof_id uuid)returns text language sql stable security definer set search_path=pg_catalog,private as $$
 select private.canonical_request_hash(jsonb_build_object('source_kind','FRANCHISE_MANDATE','franchise_id',proof.franchise_id,'mandate_id',proof.source_mandate_version_id,'version',proof.source_version,'content_hash',proof.source_hash,'issuer_org',proof.issuer_organization_id,'operator_org',proof.operator_organization_id,'policy_id',proof.policy_version_id,'document_version_id',proof.legal_document_version_id,'pdf_sha256',proof.pdf_sha256))from private.franchise_mandate_signature_proofs_v1 proof where id=p_proof_id
$$;
create function private.franchise_mandate_signature_reference_v1(p_franchise_id uuid,p_mandate_version_id uuid,p_mandate_hash text,p_operator_org_id uuid,p_actor uuid)returns jsonb language plpgsql stable security definer set search_path=pg_catalog,private set timezone='UTC' as $$
declare f public.franchises%rowtype;m public.franchise_mandate_versions%rowtype;proof private.franchise_mandate_signature_proofs_v1%rowtype;policy private.franchise_mandate_signature_policies_v1%rowtype;cfg public.signature_provider_configs%rowtype;env text;party private.franchise_mandate_signature_parties_v1%rowtype;expected text;party_hash text;begin
 if p_actor is null or p_mandate_hash is null or p_mandate_hash!~'^[0-9a-f]{64}$'then return null;end if;
 select*into f from public.franchises where id=p_franchise_id;select*into m from public.franchise_mandate_versions where id=p_mandate_version_id and franchise_id=f.id;
 if f.id is null or m.id is null or f.operator_organization_id is distinct from p_operator_org_id or m.content_hash is distinct from p_mandate_hash or not private.is_active_org_member(p_operator_org_id,p_actor)then return null;end if;
 select environment into env from private.admin_execution_environment_v1 where singleton;if env is null then return null;end if;
 if m.id is distinct from(select q.mandate_version_id from public.franchise_approval_requests q where q.franchise_id=f.id and q.status='APPROVED'order by q.decided_at desc,q.id desc limit 1)then return null;end if;
 select*into proof from private.franchise_mandate_signature_proofs_v1 where franchise_id=f.id and source_mandate_version_id=m.id and source_version=m.version and source_hash=m.content_hash and operator_organization_id=p_operator_org_id order by verified_at desc limit 1;
 if proof.id is null then return null;end if;select*into policy from private.franchise_mandate_signature_policies_v1 where id=proof.policy_version_id;select*into cfg from public.signature_provider_configs where id=policy.provider_config_id;
 if policy.id is null or policy.environment is distinct from env or cfg.environment is distinct from env or policy.issuer_organization_id is distinct from proof.issuer_organization_id or cfg.provider_code is distinct from proof.provider_code or cfg.provider_code='MATRICIA_DEV_MOCK'or cfg.status<>'ACTIVE'or cfg.valid_from>proof.completed_at or cfg.valid_until<proof.completed_at or policy.approved_at>proof.completed_at or policy.valid_until<clock_timestamp()or proof.completed_at>clock_timestamp()or proof.verified_at<proof.completed_at or proof.verified_at>clock_timestamp()or array_position(array['SIMPLE','ADVANCED','QUALIFIED'],proof.achieved_level)<array_position(array['SIMPLE','ADVANCED','QUALIFIED'],policy.minimum_level)or not(proof.achieved_level=any(cfg.supported_levels))then return null;end if;
 if not exists(select 1 from public.organizations where id=proof.issuer_organization_id and status='ACTIVE')or not exists(select 1 from public.organizations where id=p_operator_org_id and status='ACTIVE')or exists(select 1 from(values(proof.pdf_storage_object_id),(proof.evidence_storage_object_id))required(id)where not exists(select 1 from storage.objects o join storage.buckets b on b.id=o.bucket_id where o.id=required.id and not b.public))then return null;end if;
 if not exists(select 1 from jsonb_array_elements(proof.verified_events)event where event->>'event_type'='SENT')or exists(select 1 from jsonb_array_elements(proof.verified_events)event where coalesce(event->>'event_type','')not in('SENT','SIGNER_SIGNED')or length(coalesce(event->>'provider_event_id',''))not between 8 and 200 or length(coalesce(event->>'nonce',''))not between 8 and 200 or event->>'source_binding_hash'is distinct from proof.source_binding_hash or coalesce(event->>'payload_sha256','')!~'^[0-9a-f]{64}$'or coalesce(event->>'signature_fingerprint','')!~'^[0-9a-f]{64}$')or(select count(distinct event->>'provider_event_id')from jsonb_array_elements(proof.verified_events)event)<>jsonb_array_length(proof.verified_events)or(select count(distinct event->>'nonce')from jsonb_array_elements(proof.verified_events)event)<>jsonb_array_length(proof.verified_events)then return null;end if;
 if proof.source_binding_hash is distinct from private.franchise_mandate_source_binding_hash_v1(proof.id)or proof.event_chain_hash is distinct from private.canonical_request_hash(proof.verified_events)or(select count(*)from private.franchise_mandate_signature_parties_v1 where proof_id=proof.id)<>2 then return null;end if;
 for party in select*from private.franchise_mandate_signature_parties_v1 where proof_id=proof.id loop
  if party.organization_id is distinct from(case when party.party_role='ISSUER'then proof.issuer_organization_id else p_operator_org_id end)or(party.party_role='OPERATOR'and party.signer_user_id<>p_actor)or not private.is_active_org_member(party.organization_id,party.signer_user_id)or not exists(select 1 from auth.users u where u.id=party.signer_user_id and u.email_confirmed_at is not null and party.verified_email_sha256=encode(extensions.digest(lower(btrim(u.email)),'sha256'),'hex'))or party.achieved_level is distinct from proof.achieved_level or party.authority_source_hash is distinct from m.content_hash or party.authority_valid_from>party.signed_at or party.authority_valid_until<party.signed_at or party.signed_at>proof.completed_at or not exists(select 1 from jsonb_array_elements(proof.verified_events)event where event->>'event_type'='SIGNER_SIGNED'and event->>'provider_event_id'=party.provider_event_id and event->>'signer_reference'=party.provider_signer_reference and event->>'source_binding_hash'=proof.source_binding_hash and coalesce(event->>'payload_sha256','')~'^[0-9a-f]{64}$'and coalesce(event->>'signature_fingerprint','')~'^[0-9a-f]{64}$')then return null;end if;
  if policy.require_certificate and(party.certificate_status is distinct from'VERIFIED'or party.certificate_fingerprint is null or party.certificate_valid_from is null or party.certificate_valid_until is null or party.certificate_valid_from>party.signed_at or party.certificate_valid_until<party.signed_at or(proof.achieved_level='QUALIFIED'and party.certificate_qualification is distinct from'QUALIFIED'))then return null;end if;
  if policy.require_trusted_timestamp and(party.timestamp_status is distinct from'VERIFIED'or party.timestamp_token_hash is null or party.timestamped_at is null or abs(extract(epoch from(party.timestamped_at-party.signed_at)))>300)then return null;end if;
 end loop;
 select private.canonical_request_hash(jsonb_agg(to_jsonb(q)order by q.party_role))into party_hash from private.franchise_mandate_signature_parties_v1 q where proof_id=proof.id;
 expected:=private.canonical_request_hash(jsonb_build_object('source_binding_hash',proof.source_binding_hash,'provider_code',proof.provider_code,'provider_envelope_id',proof.provider_envelope_id,'provider_package_id',proof.provider_package_id,'provider_package_sha256',proof.provider_package_sha256,'level',proof.achieved_level,'event_chain_hash',proof.event_chain_hash,'parties_hash',party_hash));
 if proof.final_hash is distinct from expected then return null;end if;
 return jsonb_build_object('proofLedgerId',proof.id,'legalDocumentVersionId',proof.legal_document_version_id,'policyVersionId',policy.id,'providerCode',proof.provider_code,'signatureLevel',proof.achieved_level,'issuerOrg',proof.issuer_organization_id,'operatorOrg',proof.operator_organization_id,'signerUserId',p_actor,'sourceMandateId',m.id,'sourceVersion',m.version,'sourceHash',m.content_hash,'sourceBindingHash',proof.source_binding_hash,'finalHash',proof.final_hash);
exception when others then return null;
end$$;
create function private.franchise_mandate_signature_effective_v1(p_franchise_id uuid,p_mandate_version_id uuid,p_mandate_hash text,p_operator_org_id uuid,p_actor uuid)returns boolean language sql stable security definer set search_path=pg_catalog,private as $$select private.franchise_mandate_signature_reference_v1(p_franchise_id,p_mandate_version_id,p_mandate_hash,p_operator_org_id,p_actor)is not null$$;
revoke all on function private.franchise_mandate_source_binding_hash_v1(uuid),private.franchise_mandate_signature_reference_v1(uuid,uuid,text,uuid,uuid),private.franchise_mandate_signature_effective_v1(uuid,uuid,text,uuid,uuid)from public,anon,authenticated,service_role;
notify pgrst,'reload schema';
commit;
